BEGIN;
--
-- Create model Category
--
CREATE TABLE "b2b_orders_category" ("id" bigint NOT NULL PRIMARY KEY GENERATED BY DEFAULT AS IDENTITY, "name" varchar(100) NOT NULL, "icon" varchar(50) NOT NULL, "order" integer NOT NULL CHECK ("order" >= 0), "is_active" boolean NOT NULL, "created_at" timestamp with time zone NOT NULL);
--
-- Create model CustomUser
--
CREATE TABLE "b2b_orders_customuser" ("id" bigint NOT NULL PRIMARY KEY GENERATED BY DEFAULT AS IDENTITY, "password" varchar(128) NOT NULL, "last_login" timestamp with time zone NULL, "is_superuser" boolean NOT NULL, "username" varchar(150) NOT NULL UNIQUE, "first_name" varchar(150) NOT NULL, "last_name" varchar(150) NOT NULL, "email" varchar(254) NOT NULL, "is_staff" boolean NOT NULL, "is_active" boolean NOT NULL, "date_joined" timestamp with time zone NOT NULL, "role" varchar(20) NOT NULL, "phone_number" varchar(25) NOT NULL);
CREATE TABLE "b2b_orders_customuser_groups" ("id" bigint NOT NULL PRIMARY KEY GENERATED BY DEFAULT AS IDENTITY, "customuser_id" bigint NOT NULL, "group_id" integer NOT NULL);
CREATE TABLE "b2b_orders_customuser_user_permissions" ("id" bigint NOT NULL PRIMARY KEY GENERATED BY DEFAULT AS IDENTITY, "customuser_id" bigint NOT NULL, "permission_id" integer NOT NULL);
--
-- Create model CafeProfile
--
CREATE TABLE "b2b_orders_cafeprofile" ("id" bigint NOT NULL PRIMARY KEY GENERATED BY DEFAULT AS IDENTITY, "name" varchar(150) NOT NULL, "phone" varchar(30) NOT NULL, "address" varchar(255) NOT NULL, "logo" varchar(100) NULL, "created_at" timestamp with time zone NOT NULL, "user_id" bigint NOT NULL UNIQUE);
--
-- Create model MenuItem
--
CREATE TABLE "b2b_orders_menuitem" ("id" bigint NOT NULL PRIMARY KEY GENERATED BY DEFAULT AS IDENTITY, "name" varchar(150) NOT NULL, "description" text NOT NULL, "price" numeric(10, 2) NOT NULL, "image" varchar(100) NULL, "is_available" boolean NOT NULL, "preparation_time" integer NOT NULL CHECK ("preparation_time" >= 0), "created_at" timestamp with time zone NOT NULL, "category_id" bigint NOT NULL);
--
-- Create model Order
--
CREATE TABLE "b2b_orders_order" ("id" bigint NOT NULL PRIMARY KEY GENERATED BY DEFAULT AS IDENTITY, "order_number" varchar(40) NOT NULL UNIQUE, "table_or_customer" varchar(100) NOT NULL, "customer_notes" text NOT NULL, "status" varchar(20) NOT NULL, "total_price" numeric(10, 2) NOT NULL, "created_at" timestamp with time zone NOT NULL, "updated_at" timestamp with time zone NOT NULL, "cafe_id" bigint NOT NULL);
--
-- Create model OrderItem
--
CREATE TABLE "b2b_orders_orderitem" ("id" bigint NOT NULL PRIMARY KEY GENERATED BY DEFAULT AS IDENTITY, "item_name" varchar(150) NOT NULL, "unit_price" numeric(10, 2) NOT NULL, "quantity" integer NOT NULL CHECK ("quantity" >= 0), "subtotal" numeric(10, 2) NOT NULL, "notes" varchar(255) NOT NULL, "menu_item_id" bigint NULL, "order_id" bigint NOT NULL);
--
-- Create model RestaurantProfile
--
CREATE TABLE "b2b_orders_restaurantprofile" ("id" bigint NOT NULL PRIMARY KEY GENERATED BY DEFAULT AS IDENTITY, "name" varchar(150) NOT NULL, "description" text NOT NULL, "logo" varchar(100) NULL, "cover_image" varchar(100) NULL, "phone" varchar(30) NOT NULL, "address" varchar(255) NOT NULL, "is_active" boolean NOT NULL, "created_at" timestamp with time zone NOT NULL, "user_id" bigint NOT NULL UNIQUE);
--
-- Add field restaurant to order
--
ALTER TABLE "b2b_orders_order" ADD COLUMN "restaurant_id" bigint NOT NULL CONSTRAINT "b2b_orders_order_restaurant_id_3e7b77f0_fk_b2b_order" REFERENCES "b2b_orders_restaurantprofile"("id") DEFERRABLE INITIALLY DEFERRED; SET CONSTRAINTS "b2b_orders_order_restaurant_id_3e7b77f0_fk_b2b_order" IMMEDIATE;
--
-- Add field restaurant to menuitem
--
ALTER TABLE "b2b_orders_menuitem" ADD COLUMN "restaurant_id" bigint NOT NULL CONSTRAINT "b2b_orders_menuitem_restaurant_id_d3e0b0d8_fk_b2b_order" REFERENCES "b2b_orders_restaurantprofile"("id") DEFERRABLE INITIALLY DEFERRED; SET CONSTRAINTS "b2b_orders_menuitem_restaurant_id_d3e0b0d8_fk_b2b_order" IMMEDIATE;
--
